  if (buckets < 1 || buckets > 1000) return 'buckets is between 1 and 1000.';
  if (minutesToDie < 1) return 'minutesToDie is at least 1.';
  if (minutesToTest < minutesToDie || minutesToTest > 100) return 'minutesToTest is between minutesToDie and 100.';
  return null;
}

