function poorPigs(buckets, minutesToDie, minutesToTest) {
  // capacity(p, t): how many buckets p pigs can tell apart in t rounds (capped at buckets).
  // In the first round some k of the p pigs die (C(p, k) ways); the survivors then have t - 1 rounds.
  const rounds = Math.floor(minutesToTest / minutesToDie);
  const choose = (n, k) => { let c = 1; for (let i = 1; i <= k; i++) c = c * (n - k + i) / i; return Math.round(c); };
  const memo = new Map();
  const capacity = (p, t) => {
    if (p === 0 || t === 0) return 1;
    const key = p + ',' + t;
    if (memo.has(key)) return memo.get(key);
    let total = 0;
    for (let k = 0; k <= p; k++) total = Math.min(buckets, total + choose(p, k) * capacity(p - k, t - 1));
    memo.set(key, total);
    return total;
  };
  let p = 0;
  while (capacity(p, rounds) < buckets) p++;
  return p;
}

