function generate(rand, size) {
  const minutesToDie = 1 + Math.floor(rand() * (rand() < 0.5 ? 100 : 30));
  const minutesToTest = minutesToDie + Math.floor(rand() * (101 - minutesToDie));
  const buckets = size === 'large' ? 1000 - Math.floor(rand() * 10) : 1 + Math.floor(rand() * (rand() < 0.3 ? 20 : 1000));
  return [buckets, minutesToDie, minutesToTest];
}
